class RaftNode:
    def __init__(self, node_id):
        self.node_id = node_id
        self.term = 0
        self.voted_for = None
        self.state = 'Follower'
    def request_vote(self, candidate_id, term):
        if term > self.term:
            self.term = term
            self.voted_for = candidate_id
            return True
        return False

import heapq
class LockFreeOrderBook:
    def __init__(self):
        self.bids = []
        self.asks = []
    def push_bid(self, price, qty):
        heapq.heappush(self.bids, (-price, qty))

class SlabAllocator:
    def __init__(self, block_size, count):
        self.block_size = block_size
        self.pool = bytearray(block_size * count)
        self.free_offsets = [i * block_size for i in range(count)]
    def alloc(self):
        return self.free_offsets.pop() if self.free_offsets else None
